    /// Журнал коннектора прикладывают к обращению в поддержку — производный
    /// `Debug` печатал бы оба пароля полями как есть, и вся работа по
    /// шифрованию обнулилась бы одной отладочной строкой.
    #[test]
    fn debug_output_never_carries_a_password() {
        let mut c = filled();
        c.current_mut().db_password = "секрет-базы".into();
        let text = format!("{c:?}");
        assert!(!text.contains("секрет-базы"), "{text}");
        assert_eq!(text.matches("<скрыт>").count(), 1);
        assert!(text.contains(&c.current().name), "отладка не должна ослепнуть");
    }

    /// Клиент-серверная база против файловой и сетевой. Решает то, что
    /// стоит до первого слэша: буква диска — файловая, имя сервера (хоть с
    /// портом кластера) — клиент-серверная. Прежняя копия правила смотрела
    /// на двоеточие где угодно и относила `сервер:1541\база` к файловым, а
    /// сетевой путь — к клиент-серверным.
    #[test]
    fn a_server_base_is_told_from_a_file_one_by_what_stands_before_the_slash() {
        assert!(is_server_base(r"srv-1c\unf"));
        assert!(is_server_base(r"srv-1c:1541\unf"), "порт кластера — всё ещё клиент-серверная");
        assert!(!is_server_base(r"C:\Bases\Buh"));
        assert!(!is_server_base(r"\nas\share\Buh"), "сетевой путь — файловая база");
        assert!(!is_server_base("/home/dev1/base"), "linux-путь без обратных слэшей");
        assert!(!is_server_base(""));
    }

    /// Образец — ровно то, что `render` напечатал бы для умолчаний: ни одного
    /// выдуманного значения, всё пусто или умолчание (решение владельца
    /// 26.10). Задача 3 сравнивает СОЕДИНЕНИЕ, а не весь `Cfg`: поля `host`
    /// у `Cfg` больше нет, единственный блок `[[connection]]` образца читается
    /// как единственное соединение, а `Cfg::default()` — это свежий
    /// комплект, где файла нет вовсе и соединений тоже. Имя — то, что несёт
    /// сам блок (`FIRST_CONNECTION_NAME`), не выдумка разбора.
    #[test]
    fn example_parses_and_equals_defaults() {
        let c = sample();
        // Ключа в образце нет (решение владельца 10.11), и в разобранном соединении поле `id_in_file` поэтому пусто — ровно как у
        // умолчания. Сам ключ при этом есть и выведен из имени, и это проверяется строкой ниже, а не этим сравнением.
        assert_eq!(c.current(), &Connection { name: FIRST_CONNECTION_NAME.into(), ..Connection::default() });
        assert_eq!(c.current().id(), CardId::from_name(FIRST_CONNECTION_NAME), "ключ выведен из имени, пока его нет в файле");
        assert_eq!(c.current, FIRST_CONNECTION_NAME, "единственное соединение файла оно же и текущее");
    }

    /// Задача 8 плана «Модель соединений». Сравнение имён — ТОЧНОЕ, без
    /// `trim` (тем же приёмом, что `current()` и проверка повтора имён в
    /// `validate()`): отказ на несуществующем имени обязан перечислить, из
    /// чего выбирать.
    #[test]
    fn switching_the_current_connection_names_what_it_refuses() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        c.switch_current("Ромашка").unwrap();
        assert_eq!(c.current, "Ромашка");
        let e = c.switch_current("Лютик").unwrap_err();
        assert!(e.contains("Лютик") && e.contains("Buh") && e.contains("Ромашка"), "отказ перечисляет, из чего выбирать: {e}");
    }

    /// Долг задачи 8: список соединений пуст (свежий комплект, команда
    /// `use` набрана раньше первой настройки) — отказ обязан быть
    /// человеческой фразой, той же, что уже говорит `connections_overview`,
    /// а не обрезанным «…есть » без имён и без точки.
    ///
    /// Minor 3 ревью всей ветки: эту же фразу теперь произносит ОКНО
    /// (`gui::tray::apply_access`, `ops_host::write_derived_fields`), и она
    /// обязана годиться обоим читателям. Поэтому она называет МЕСТО, где
    /// заводится соединение (вкладка «Связь»), и в ней нет жаргона запуска:
    /// человеку, который на окно и смотрит, прежнее «настройте первое в окне
    /// (1c-connect gui)» говорило идти туда, где он уже стоит.
    #[test]
    fn switching_the_current_connection_on_an_empty_list_says_so_in_words() {
        let mut c = cfg_with(&[]);
        let e = c.switch_current("Buh").unwrap_err();
        assert!(e.contains("пока нет") && e.contains("«Связь»"), "фраза называет место: {e}");
        assert!(!e.contains("gui"), "жаргона запуска в ней нет ни для кого: {e}");
        assert!(!e.trim_end().ends_with("есть"), "предложение не обрывается на «есть»: {e}");
    }

    /// Расщепление `validate` на правила СПИСКА и годность ТЕКУЩЕЙ карточки
    /// (решение ведущего, вторая волна починки по ревью всей ветки).
    /// `validate_list` пропускает незаполненную карточку — ровно это и нужно
    /// заведению новой (`gui::save::add_connection`: карточка заводится
    /// пустой нарочно), — а полная `validate` не изменилась ни на шаг: она
    /// по-прежнему спрашивает и список, и поля текущей, и командная строка с
    /// «Сохранить» видят то же, что видели.
    #[test]
    fn the_list_rules_and_the_current_cards_fields_are_two_separate_questions() {
        let mut c = cfg_with(&["Buh"]);
        c.current_mut().base_path = String::new();
        c.validate_list().expect("правила списка к пустому полю карточки не придираются");
        let e = c.validate().unwrap_err().to_string();
        assert!(e.contains("base_path"), "полная проверка спрашивает поля текущей как раньше: {e}");

        // А правила списка — целиком: пустой список отказывает и здесь, не
        // только в полной проверке.
        let empty = cfg_with(&[]);
        assert!(empty.validate_list().unwrap_err().to_string().contains("ни одного соединения"));
        // И парные запреты тоже здесь: две карточки к одной базе.
        let mut twins = cfg_with(&["Buh", "Ромашка"]);
        twins.connections[1].base_path = twins.connections[0].base_path.clone();
        assert!(twins.validate_list().unwrap_err().to_string().contains("одна база, одно соединение"));
    }

    /// Шаг 5 задачи 8: `1c-connect use` без имени — список соединений,
    /// текущее отмечено. Текст человеку, не разбор кода — поэтому
    /// проверяем по смыслу (оба имени на месте, текущее узнаваемо отмечено,
    /// а не прежнее), а не побайтовым сравнением со строкой.
    #[test]
    fn listing_without_a_name_shows_every_connection_with_the_current_one_marked() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        c.switch_current("Ромашка").unwrap();
        let text = c.connections_overview();
        assert!(text.contains("Buh") && text.contains("Ромашка"), "{text}");
        let buh_line = text.lines().find(|l| l.contains("Buh")).unwrap();
        let romashka_line = text.lines().find(|l| l.contains("Ромашка")).unwrap();
        assert_ne!(buh_line.trim_end(), romashka_line.trim_end(), "текущее должно отличаться в тексте от остальных");
    }

    /// Minor 1 круга починки 1 задачи 6 плана «После живого прогона»: пустой
    /// список здесь отказывал ВТОРЫМ литералом тех же слов, от которых
    /// владелец 9.11 отвёл окно («так не пишут») — «настройте первое в окне
    /// (1c-connect gui)». `connections_overview` обязана звать тот же
    /// единственный источник, что `switch_current` (`no_connections_refusal`),
    /// а не держать свою копию: тест сравнивает со СЛОВАМИ, а не только с
    /// отсутствием старых — иначе он не упал бы, если фраза уедет в третьи,
    /// никем не одобренные слова.
    #[test]
    fn listing_on_an_empty_list_speaks_the_one_shared_refusal() {
        assert_eq!(cfg_with(&[]).connections_overview(), Cfg::no_connections_refusal());
    }

    #[test]
    fn mode_defaults_to_local_accepts_tunnel_and_rejects_the_rest() {
        // Умолчание локальное: поле не вписали — значит всё на одной машине,
        // и ни адреса среды, ни логина в ней человек не вводит.
        let without: Cfg = toml::from_str(&EXAMPLE.replace("mode = \"local\"", "")).unwrap();
        assert_eq!(without.current().mode, "local");
        let local: Cfg = toml::from_str(EXAMPLE).unwrap();
        assert_eq!(local.current().mode, "local");
        let tunnel: Cfg = toml::from_str(&EXAMPLE.replace("mode = \"local\"", "mode = \"tunnel\"")).unwrap();
        assert_eq!(tunnel.current().mode, "tunnel");
        let store = secrets::Store::file(&tmp("mode"));
        assert!(local.render(&store).unwrap().contains("mode = \"local\""));
        // Проверку заполненности гоняем на заполненном: образец пуст нарочно.
        let mut filled_local = filled();
        filled_local.current_mut().mode = "local".into();
        filled_local.validate().unwrap();
        let mut odd = crate::cfg::filled_for_test();
        odd.current_mut().mode = "remote".into();
        let why = odd.validate().unwrap_err().to_string();
        assert!(why.contains("mode"), "{why}");
        // Отказ объясняет режимы нынешним замыслом, а не прежним «база
        // внутри образа»: локальный режим — это всё на одной машине, и
        // коннектор с 29.10 не приставка к пилоту, а приложение для
        // 1С-разработчика (журнал владельца).
        assert!(!why.contains("образ"), "{why}");
        assert!(why.contains("на одной машине"), "{why}");
    }

    /// Красный тест задачи 6, буквально из брифа: числа, которые раньше
