    #[test]
    fn an_explicit_port_wins() {
        let mut c = sample();
        c.current_mut().http_port = Some(9000);
        // `127.0.0.1` — адрес прибит к тому семейству, которое слушает httpd
        // (круг исправления 2).
        assert_eq!(c.base_url(), "http://127.0.0.1:9000/hs/mcp-1c");
    }

    /// Круг исправления задачи 1 плана «тонкий срез ценности»: выбранный в
    /// этом сеансе порт (`resolved_http_port`, который проставляет
    /// `ops_host::settle_chosen_http_port`) побеждает И явный `http_port`
    /// человека, И выведенный — иначе `base_url()` называл бы не тот порт,
    /// на котором на самом деле поднят httpd (`publication::Paths::of`
    /// читает его же выбором, `ports::choose`), и агент шёл бы в молчание.
    #[test]
    fn a_resolved_port_wins_over_both_the_explicit_and_the_derived_one() {
        let mut c = sample();
        c.resolved_http_port = Some(9100);
        assert_eq!(c.http_port(), 9100, "ничего не задано кроме выбранного — он и побеждает");
        c.current_mut().http_port = Some(9000);
        assert_eq!(c.http_port(), 9100, "выбранный сильнее явного порта человека");
        // `127.0.0.1` — адрес прибит к тому семейству, которое слушает httpd
        // и проверяет страж (круг исправления 2).
        assert_eq!(c.base_url(), "http://127.0.0.1:9100/hs/mcp-1c");
    }

    /// Круг исправления 3, находка ведущего: `first_attempt_ports()` обязана
    /// нести ПРЕДПОЧТЕНИЕ (явный порт человека или вывод), а не уже
    /// УЛАЖЕННЫЙ — иначе `ports::choose` кормили бы его же прошлым выбором,
    /// и вход замыкался бы сам на себя: новое предпочтение человека до
    /// подбора не доходило бы никогда.
    #[test]
    fn first_attempt_ports_is_the_preference_not_the_already_resolved_port() {
        let mut c = sample();
        c.current_mut().http_port = Some(9000);
        c.resolved_http_port = Some(12345); // уже улажено на что-то совсем другое
        assert_eq!(c.first_attempt_ports().http, 9000, "предпочтение — явный порт человека, не то, что уже выбрано");
    }

    /// `render`/`write_checked` печатают только `current().http_port` — поле
    /// `resolved_http_port` в файл не идёт никогда (та же защита, что у
    /// `undecryptable`): иначе выбор этого сеанса застыл бы в toml навсегда
    /// при следующем «Сохранить», хотя человек его не вводил.
    #[test]
    fn resolved_http_port_never_reaches_the_rendered_file() {
        let store = secrets::Store::file(&tmp("resolved-port-render"));
        let mut c = filled();
        c.resolved_http_port = Some(12345);
        let text = c.render(&store).unwrap();
        assert!(!text.contains("12345"), "{text}");
    }

