    /// Задача 9 плана «Модель соединений»: решение владельца 7 — профиль
    /// («Разработчик»/«Бизнес-пользователь») это поле КАРТОЧКИ, не машины.
    /// Переключили текущее соединение — переключился и набор инструментов
    /// ребёнка; негодное значение отказывает словами, как и прежде.
    #[test]
    fn the_toolset_follows_the_current_connection_not_the_machine() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        c.connections[0].profile = "business".into();
        c.connections[1].profile = "developer".into();
        c.current = "Buh".into();
        assert_eq!(c.toolset().unwrap(), "business");
        c.current = "Ромашка".into();
        assert_eq!(c.toolset().unwrap(), "developer", "переключили соединение — переключился и набор");
        c.current_mut().profile = "мусор".into();
        assert!(c.toolset().is_err(), "негодное значение отказывает словами, как и прежде");
    }

    /// Круг починки 1/5 задачи 9: доказательство переноса идёт через
    /// настоящий `Cfg::load_unchecked`, а не через присвоение `profile` в
    /// памяти (так делают соседний тест и красный тест брифа — оба ничего
    /// не говорят про файл, где `profile` вообще не записан). Блок с
    /// прежним ключом `toolset`, без единого `profile`, — обязан
    /// прочитаться так, что `toolset()` отвечает прежним значением, оно же
    /// лежит в `profile`, а старое поле погашено: второй живой копии после
    /// разбора не остаётся.
    ///
    /// Задача 15 плана «Интерфейс» убрала секцию `[host]` как форму файла,
    /// но перенос `toolset` → `profile` — общее правило разбора КАЖДОГО
    /// блока `[[connection]]`, а не особенность старой формы, и переживает
    /// её удаление без изменений: фикстура здесь и прежде была бы блоком
    /// соединения, если бы не образец эталонного комплекта под рукой.
    #[test]
    fn a_connection_with_the_old_toolset_key_migrates_it_into_profile_on_load() {
        let kit =
            kit_with("current = \"Buh\"\n\n[[connection]]\nname = \"Buh\"\nbase_path = \"C:\\\\Bases\\\\Buh\"\ntoolset = \"developer\"\n");
        let c = Cfg::load_unchecked(&kit).unwrap();
        assert_eq!(c.toolset().unwrap(), "developer", "старое значение toolset продолжает действовать");
        assert_eq!(c.current().profile, "developer", "значение переехало в profile");
        assert_eq!(c.current().toolset, "", "старое поле погашено — второй копии не остаётся");
    }

    /// Тот же приём, что у `configuration()`: именованный, но неизвестный
    /// набор инструментов — отказ со списком допустимых, а не молчаливый
    /// откат на `business`.
    #[test]
    fn an_unknown_toolset_is_refused_with_the_allowed_list_in_words() {
        let mut c = sample();
        c.current_mut().profile = "бухгалтер".into();
        let err = c.toolset().unwrap_err();
        assert!(err.contains("developer") && err.contains("business"), "{err}");
    }

    /// Тот же отказ доезжает через `validate()` — та же причина, что у
    /// `configuration`: без этого опечатка тихо стала бы `business` только
    /// внутри `mcp_command`.
    #[test]
    fn validate_rejects_an_unknown_toolset() {
        let mut c = filled();
        c.current_mut().profile = "бухгалтер".into();
        let err = c.validate().unwrap_err().to_string();
        assert!(err.contains("toolset") && err.contains("developer"), "{err}");
        c.current_mut().profile = "developer".into();
        assert!(c.validate().is_ok());
    }

    /// Неизвестное слово в поле КАРТОЧКИ — отказ со списком допустимых
    /// (`validate`). Потолок МАШИНЫ сюда не приходит вовсе: у него тип о двух
    /// значениях, и третье отсекает разбор файла (`WriteCeiling::try_from`,
    /// свой тест ниже).
    #[test]
    fn validate_rejects_an_unknown_write_ceiling() {
        let mut c = filled();
        c.current_mut().write = "может быть".into();
        let err = c.validate().unwrap_err().to_string();
        assert!(err.contains("write") && err.contains("read_only") && err.contains("read_write"), "{err}");
        c.current_mut().write = "read_write".into();
        assert!(c.validate().is_ok());
        assert_eq!(c.access(), "read_only", "потолок машины полем карточки не назначается");
    }

    /// Тот же приём и тот же довод, что у `toolset`/`configuration` выше:
    /// именованная, но неизвестная роль — отказ со списком допустимых значений
    /// через `validate()`, а не молчаливый откат на `accept` у того, кто решает
    /// по роли. Пустая роль — законное значение (умолчание `accept`), и этот
    /// тест её не трогает: отказывает только мусорное слово «сервер».
    #[test]
    fn validate_rejects_an_unknown_role() {
        let mut c = filled();
        c.current_mut().role = "сервер".into();
        let err = c.validate().unwrap_err().to_string();
        assert!(err.contains("role") && err.contains("accept") && err.contains("dial"), "{err}");
        c.current_mut().role = "dial".into();
        assert!(c.validate().is_ok());
    }

    /// Круг починки 1 задачи 7 плана «Карточка публикации и удаление»,
    /// Important 1: единственное и множественное число причины обязаны
    /// нести один и тот же хвост (`UNDECRYPTABLE_REASON`) — если его
    /// переформулируют, обе фразы обязаны поехать вместе, а не одна из
    /// них. Тест ловит именно разъезд: он не хранит слова сам, а строит
    /// ожидаемое из той же константы, которой пользуется сама функция.
    #[test]
    fn undecryptable_reason_agrees_in_number_and_shares_one_tail() {
        assert_eq!(undecryptable_reason(false), format!("пароль зашифрован {UNDECRYPTABLE_REASON}"));
        assert_eq!(undecryptable_reason(true), format!("пароли зашифрованы {UNDECRYPTABLE_REASON}"));
    }

    /// Буквально из брифа задачи 13: прежний файл (и свежий файл без поля
    /// `role` вовсе) обязан читаться, а не отказывать — умолчание «accept»
    /// совпадает с прежним поведением принимающей стороны.
    #[test]
    fn a_connection_without_a_role_in_the_file_accepts_connections() {
        let c: Cfg = toml::from_str("[[connection]]\nname = \"Buh\"\n").unwrap();
        assert_eq!(c.connections[0].role().unwrap(), "accept");
    }

    /// Тот же приём, что у `configuration()`/`toolset()`: именованная, но
    /// неизвестная роль — отказ словами со списком допустимых, который
    /// доезжает и через `Connection::validate()` напрямую (бриф задачи 13).
    #[test]
    fn an_unknown_role_is_refused_with_the_allowed_values_named() {
        let c = Connection { role: "мусор".into(), ..Default::default() };
        let e = format!("{:#}", c.validate().unwrap_err());
        assert!(e.contains("accept") && e.contains("dial"), "{e}");
    }

    /// `current` указывает именем (решение плана, 2.11) — два одинаковых
    /// имени делают текущее неопределённым, а пустое имя нечем показать в
    /// списке соединений.
    #[test]
    fn two_connections_cannot_share_a_name_and_none_can_be_nameless() {
        let same = cfg_with(&["Buh", "Buh"]);
        let e = same.validate().unwrap_err();
        assert!(format!("{e:#}").contains("Buh"), "отказ называет повторяющееся имя: {e:#}");

        let nameless = cfg_with(&[""]);
        assert!(nameless.validate().is_err(), "безымянное соединение в списке не показать");

        assert_eq!(default_name(r"C:\Bases\Buh", &[]), "Buh");
        assert_eq!(default_name(r"C:\Bases\Buh", &["Buh"]), "Buh 2", "занятое имя получает номер, а не отказ");
    }

    /// Хвостовой номер базового имени — свой, не чужой: «Соединение 1»
    /// (`FIRST_CONNECTION_NAME`) уже оканчивается числом, и вторая карточка
    /// обязана нарастить ЕГО, а не приписать второе число через пробел —
    /// «Соединение 1 2» ничего не говорит человеку, «Соединение 2» говорит
    /// всё (замер на живом окне 9.11). Имя, выведенное из каталога базы
    /// («Buh»), числа не несёт — для него правило прежнее: «Buh 2».
    #[test]
    fn the_second_card_is_named_after_the_first_not_after_its_whole_name() {
        assert_eq!(default_name("", &["Соединение 1"]), "Соединение 2");
        assert_eq!(default_name("", &["Соединение 1", "Соединение 2"]), "Соединение 3");
        assert_eq!(default_name(r"C:\Bases\Buh", &["Buh"]), "Buh 2");
    }

    /// Круг починки 1 задачи 1, находка Important: число в хвосте имени,
    /// выведенного из каталога базы, не наш счётчик, а часть имени, которое
    /// дал человек (год, версия) — наращивать его нельзя. Карточка к базе
    /// «База 2024» на занятом имени обязана получить «База 2024 2», а не
    /// «База 2025»: вторая карточка к той же базе — это не «следующий год»,
    /// который человек прочитал бы как ДРУГУЮ базу.
    #[test]
    fn a_year_in_a_derived_name_is_not_our_counter() {
        assert_eq!(default_name(r"C:\Bases\База 2024", &["База 2024"]), "База 2024 2");
    }

    /// Круг починки 1/5 задачи 10, решение координатора: ПОЛЯ спрашиваются у
    /// ТЕКУЩЕЙ карточки, а список — только для адресации и парных запретов.
    /// Негодная соседняя карточка (человек дописал блок руками и не заполнил
    /// поля) не имеет права запирать работу с исправной текущей: у окна поля
    /// чужой карточки не показаны вовсе, и человеку из такого отказа некуда
    /// идти. Своя беда откажет, когда карточку сделают текущей — здесь
    /// проверяются оба конца этого правила.
    #[test]
    fn a_broken_neighbour_does_not_refuse_the_current_card_but_refuses_when_it_becomes_current() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        c.connections[1].base_path = String::new();
        c.validate().expect("поля чужой карточки не судят работу с текущей");

        c.current = "Ромашка".into();
        let e = c.validate().unwrap_err();
        assert!(format!("{e:#}").contains("Ромашка"), "своя беда откажет словами и назовёт карточку: {e:#}");
    }

    /// Другая половина того же решения: ослаблена ровно проверка ПОЛЕЙ.
    /// Уникальность имён держит адресацию записи (на двух одноимённых блоках
    /// `set_named`/`previous_literal` починят первый, а беда во втором), а
    /// парные запреты судятся только по паре — ни то, ни другое по одной
    /// карточке не проверить, и ослаблению они не подлежат. Беда в обоих
    /// случаях у НЕ текущей карточки.
    #[test]
    fn the_list_rules_still_judge_every_card_even_a_foreign_one() {
        let dup = cfg_with(&["Buh", "Buh"]);
        assert!(dup.validate().is_err(), "два одноимённых блока ломают адресацию записи");

        let mut same_base = cfg_with(&["Buh", "Ромашка"]);
        same_base.connections[1].base_path = same_base.connections[0].base_path.clone() + "\\";
        assert!(same_base.validate().is_err(), "одна база — одна карточка, и это про пару");

        let mut nested = cfg_with(&["Buh", "Ромашка"]);
        nested.connections[1].project = format!("{}\\src", nested.connections[0].project);
        assert!(nested.validate().is_err(), "папка принадлежит одному соединению, и это тоже про пару");

        let mut nameless = cfg_with(&["Buh", "Ромашка"]);
        nameless.connections[1].name = String::new();
        assert!(nameless.validate().is_err(), "безымянную карточку нечем показать в списке и нечем адресовать");
    }

    /// Находка 6 ревью всей ветки (MINOR): а если два одноимённых блока всё
    /// же лежат на диске (чтение такой файл отвергает, но правка руками его
    /// создаёт), писатель брал ПЕРВЫЙ молча — `.find()`, — а беда могла быть
    /// во втором: на таком файле подстановка прежнего шифртекста способна
    /// перенести ЧУЖОЙ пароль в чужое место. Отказ словами вместо догадки;
    /// какой из двух блоков его, решает человек.
    #[test]
    fn two_blocks_with_one_name_are_a_refusal_not_a_guess() {
        let text = "[[connection]]\nname = \"Buh\"\ndb_password = \"первый\"\n\n[[connection]]\nname = \"Buh\"\ndb_password = \"второй\"\n";
        let e = block_in(text, "Buh").unwrap_err();
        assert!(e.contains("Buh") && e.contains("два блока"), "{e}");
        assert!(set_named(text, "Buh", "db_password", "\"третий\"").is_err(), "писать наугад в один из двух нельзя");
        assert_eq!(previous_literal(text, "Buh", "db_password"), None, "чей из двух это шифртекст — неизвестно");
        // Один блок тем же именем по-прежнему находится и правится.
        let one = "[[connection]]\nname = \"Buh\"\ndb_password = \"первый\"\n";
        assert_eq!(block_in(one, "Buh"), Ok(0));
        assert_eq!(previous_literal(one, "Buh", "db_password").as_deref(), Some("\"первый\""));
    }

    /// Главный тест задачи: удаление карточки — это вырезание ТЕКСТА её
    /// блока, а не перепечатка файла по памяти. У соседнего блока лежит
    /// ЗАШИФРОВАННЫЙ пароль, который на этой машине мог не открыться
    /// (`Cfg::undecryptable`) — перепечатка подставила бы на его место
    /// пустую строку (это чуть не случилось в прошлой ветке и было поймано
    /// ревью как Critical). Поэтому байты соседнего блока обязаны остаться
    /// ровно такими же, как были.
    #[test]
    fn remove_named_cuts_the_named_block_and_leaves_the_foreign_ciphertext_untouched() {
        let text = "current = \"Buh\"\n\n[[connection]]\nname = \"Buh\"\ndb_password = \"ШИФР-Buh\"\n\n[[connection]]\nname = \"Ромашка\"\ndb_password = \"ШИФР-Ромашка\"\n";
        let out = remove_named(text, "Buh").unwrap();
        assert_eq!(out, "current = \"Buh\"\n\n[[connection]]\nname = \"Ромашка\"\ndb_password = \"ШИФР-Ромашка\"\n");
    }

    /// Имени нет ни в одном блоке — отказ тем же словами, что у `block_in` на
    /// расхождении файла с памятью (`stale_file`): заводить второе слово
    /// отказа незачем, причина одна.
    #[test]
    fn remove_named_refuses_a_name_that_is_not_in_the_file() {
        let text = "[[connection]]\nname = \"Buh\"\n";
        let e = remove_named(text, "Ромашка").unwrap_err();
        assert!(e.contains("Ромашка") && e.contains("настройки на диске изменились"), "{e}");
    }

    /// Два блока с одним именем — отказ, тот же `duplicate_block`, что у
    /// `block_in`: догадка, какой из двух вырезать, стоила бы ЧУЖОГО пароля.
    /// Текст при отказе не меняется вовсе.
    #[test]
    fn remove_named_refuses_two_blocks_with_the_same_name() {
        let text = "[[connection]]\nname = \"Buh\"\ndb_password = \"первый\"\n\n[[connection]]\nname = \"Buh\"\ndb_password = \"второй\"\n";
        let e = remove_named(text, "Buh").unwrap_err();
        assert!(e.contains("Buh") && e.contains("два блока"), "{e}");
    }

    /// Буквально из брифа задачи 5: хвостовой разделитель, `\.` в конце и
    /// серверная строка против файлового пути — одинаково на обеих системах.
    /// Регистр — отдельными тестами ниже, под `#[cfg(windows)]`/`#[cfg(unix)]`
    /// (решение координатора: проза брифа про системы главнее кода его же
    /// примера, который сравнивал регистр без разбора).
    #[test]
    fn the_same_base_written_differently_is_still_the_same_base() {
        assert!(same_base(r"C:\Bases\Buh", r"C:\Bases\Buh\"), "хвостовой разделитель не делает базу другой");
        assert!(same_base(r"C:\Bases\Buh", r"C:\Bases\Buh\."), "`\\.` в конце — тот же самый каталог");
        assert!(!same_base(r"C:\Bases\Buh", r"C:\Bases\Buh2"));
        assert!(!same_base(r"Срв\Buh", r"C:\Bases\Buh"), "серверная строка и файловый путь — разные базы");
    }

    /// На Windows пути регистронезависимы: `C:\Bases\Buh` и `c:\bases\buh\` —
    /// одна и та же база.
    #[test]
    #[cfg(windows)]
    fn same_base_ignores_case_on_windows() {
        assert!(same_base(r"C:\Bases\Buh", r"c:\bases\buh\"));
    }

    /// На Linux пути регистрозависимы НА САМОМ ДЕЛЕ — это разные папки на
    /// диске, и `same_base` обязана это уважать, а не склеивать их в одну
    /// базу ложной гарантией (решение координатора).
    #[test]
    #[cfg(unix)]
    fn same_base_respects_case_on_unix() {
        assert!(!same_base(r"C:\Bases\Buh", r"c:\bases\buh"), "на Linux регистр делает базу другой");
    }

    /// Буквально из брифа задачи 6: совпадение и вложенность в обе стороны —
    /// конфликт, соседство по имени — нет (сравнение обязано идти по
    /// КОМПОНЕНТАМ пути, а не по префиксу строки), и пустая папка не
    /// конфликтует ни с чем — её ещё не выбрали.
    #[test]
    fn a_folder_inside_another_connections_folder_is_a_conflict_both_ways() {
        assert!(folder_conflict(r"C:\work\Buh", r"C:\work\Buh"));
        assert!(folder_conflict(r"C:\work", r"C:\work\Buh"), "родитель и ребёнок — конфликт");
        assert!(folder_conflict(r"C:\work\Buh", r"C:\work"), "и в обратную сторону тоже");
        assert!(!folder_conflict(r"C:\work\Buh", r"C:\work\Buh2"), "сосед по имени — не вложенность");
        assert!(!folder_conflict("", r"C:\work"), "пустая папка не конфликтует ни с чем: её ещё не выбрали");
    }

    /// Находка 1 ревью ВСЕЙ ветки (CRITICAL): оба твёрдых запрета обходились
    /// написанием пути. Нормализация снимала только ХВОСТ — разделитель и
    /// `\.` в конце, — а те же самые знаки В СЕРЕДИНЕ пути проходили как
    /// есть: `C:/Bases/Buh` и `C:\Bases\Buh` считались разными базами, а
    /// `C:\work\.\Buh` расходился по компонентам с `C:\work\Buh` и выводил
    /// папку из-под запрета. Цена названа владельцем: две карточки в одной
    /// папке — невосстановимая потеря файлов (у документов нет истории),
    /// две карточки к одной базе — отказ платформы 1С без объяснения причины.
    #[test]
    fn a_dot_or_another_separator_inside_the_path_does_not_make_it_a_different_path() {
        assert!(same_base(r"C:/Bases/Buh", r"C:\Bases\Buh"), "разделитель в середине не делает базу другой");
        assert!(same_base(r"C:\Bases\.\Buh", r"C:\Bases\Buh"), "`.` в середине — тот же самый каталог");
        assert!(folder_conflict(r"C:\work\.\Buh", r"C:\work\Buh"), "`.` в середине не выводит папку из-под запрета");
        assert!(folder_conflict(r"C:/work/Buh", r"C:\work\Buh\src"), "вложенность видна и через другой разделитель");
        // А соседство по имени — по-прежнему не одно и то же: нормализация
        // склеивает написания, а не разные папки.
        assert!(!same_base(r"C:/Bases/Buh", r"C:\Bases\Buh2"));
        assert!(!folder_conflict(r"C:/work/Buh", r"C:\work\Buh2"));
    }

    /// Та же проверка через `validate()`: вторая карточка к той же базе,
    /// по-другому записанной, — отказ, называющий ПОЗДНЕЕ в списке имя, та же
    /// мерка, что у проверки повторяющихся имён выше. Разница только в
    /// хвостовом разделителе — без смены регистра, нарочно: тест обязан
    /// проходить и на Linux, где `same_base` регистр не склеивает.
    #[test]
    fn validate_rejects_a_second_card_to_the_same_base_written_differently() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        let same = format!("{}\\", c.connections[0].base_path);
        c.connections[1].base_path = same;
        let e = format!("{:#}", c.validate().unwrap_err());
        assert!(e.contains("Ромашка") && e.contains("Buh") && e.contains("одна база"), "{e}");
        // Внутри ОДНОЙ фразы человеку — одно слово про одну сущность (находка
        // 4 ревью всей ветки: хвост этой фразы был взят из словаря окна, а
        // модель — и обе первые половины фразы — говорит «соединение»).
        assert!(e.contains("одна база, одно соединение"), "{e}");
    }

    /// Круг починки 1, Important (ревью после отчёта задачи 5): пустой
    /// `base_path` — это «путь не введён», а не «занятая база». Парное
    /// сравнение `same_base` выше стоит ДО `c.validate()?` по каждому
    /// соединению и, не будь этой защиты, признало бы ЛЮБУЮ пару пустых
    /// путей «той же базой» (`same_base("", "")` истинно), заслоняя собой
    /// понятный отказ «base_path — путь к базе» сбивающим «эта же база уже
    /// занята». Достижимо только правкой toml руками — окно такую пару не
    /// даёт создать (`gui::save::same_base_conflict` — тот же приём, уже
    /// стоявший там), но бриф прямо заботится о человеке, который правил
    /// файл руками и должен узнать, что опечатался.
    #[test]
    fn two_unfilled_connections_are_refused_about_the_empty_path_not_about_a_shared_base() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        c.connections[0].base_path = String::new();
        c.connections[1].base_path = String::new();
        let e = format!("{:#}", c.validate().unwrap_err());
        assert!(e.contains("base_path") && e.contains("путь к базе"), "{e}");
        assert!(!e.contains("занята"), "пустая пара — не конфликт базы: {e}");
    }

    /// Задача 6 плана «Модель соединений»: та же защита, что у `same_base`
    /// выше, но на поле `project`, а не `base_path` — отдельный блок
    /// `validate()`, отдельный тест. Вложенность ловится так же твёрдо, как
    /// совпадение, и отказ называет ПОЗДНЕЕ в списке имя — та же мерка.
    #[test]
    fn validate_rejects_a_second_cards_folder_nested_inside_the_first() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        let parent = c.connections[0].project.clone();
        c.connections[1].project = format!("{parent}\\src");
        let e = format!("{:#}", c.validate().unwrap_err());
        assert!(e.contains("Ромашка") && e.contains("Buh") && e.contains("папка принадлежит одному соединению"), "{e}");
    }

    /// Путь с `..` — отказ СЛОВАМИ, а не нормализация за человека. Довод не в
    /// красоте: защита «папка принадлежит одному соединению» сравнивает пути ПО
    /// КОМПОНЕНТАМ (`folder_conflict`), и `C:\work\Buh\..\Buh2` при таком сравнении
    /// не совпадает с `C:\work\Buh2`, хотя это одно и то же место. То есть `..`
    /// проходит мимо защиты — и два соединения оказываются в одной папке, где у
    /// документов нет истории. Чинить это складыванием `..` внутри `normalize_base`
    /// нельзя: `..` через ссылку на каталог ведёт НЕ туда, куда ведёт по строке, и
    /// складывание дало бы ложное «это разные папки» там, где они одна.
    #[test]
    fn validate_rejects_a_folder_with_a_parent_component() {
        let mut c = cfg_with(&["Buh"]);
        c.connections[0].project = r"C:\work\Buh\..\Buh2".into();
        let e = format!("{:#}", c.validate().unwrap_err());
        assert!(e.contains("Buh") && e.contains(".."), "{e}");
    }

    /// То же для пути базы: её сравнивает `same_base`, и той же меркой — по
    /// нормализованной строке, где `..` остаётся компонентом. Две карточки к одной
    /// базе — отказ платформы 1С без объяснения причины.
    #[test]
    fn validate_rejects_a_base_path_with_a_parent_component() {
        let mut c = cfg_with(&["Buh"]);
        c.connections[0].base_path = r"C:\bases\..\Buh".into();
        let e = format!("{:#}", c.validate().unwrap_err());
        assert!(e.contains("Buh") && e.contains(".."), "{e}");
    }

    /// Имя каталога, которое лишь НАЧИНАЕТСЯ на две точки, — не `..`: `C:\work\..тайное`
    /// законный путь, и отказывать на нём значило бы запрещать человеку его же папку.
    /// Проверка идёт по компонентам, а не поиском подстроки.
    #[test]
    fn a_folder_whose_name_starts_with_two_dots_is_not_a_parent_component() {
        let mut c = cfg_with(&["Buh"]);
        c.connections[0].project = r"C:\work\..тайное".into();
        let r = c.validate();
        assert!(r.is_ok(), "{:#}", r.unwrap_err());
    }

    /// Симметрия с задачей 5 (урок круга починки 1, перенесённый в этот план
    /// координатором с самого начала задачи): пустой `project` — это «папка
    /// не задана», а не «папка уже занята» чужим столь же пустым полем.
    /// Пустой `project` годен обоим соединениям (умолчание инструментов —
    /// `business`, у которого каталога исходников нет вовсе).
    #[test]
    fn two_unfilled_project_folders_are_not_a_conflict() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        c.connections[0].project = String::new();
        c.connections[1].project = String::new();
        let r = c.validate();
        assert!(r.is_ok(), "{:#}", r.unwrap_err());
    }

    /// Задача 15 плана «Интерфейс»: файл, в котором есть И прежняя секция
    /// `[host]`, И блоки `[[connection]]`, — тот же отказ, что у файла с
    /// одной только `[host]` (`an_old_host_only_file_is_refused_in_words_by_every_reader`
    /// в начале модуля): присутствие секции само по себе уже отказ, и
    /// разбираться, есть ли рядом список, незачем. У обоих читателей,
    /// командной строки и окна, — один и тот же отказ, а не прежняя
    /// развилка «командная строка отказывает, окно терпит».
    #[test]
    fn a_file_carrying_both_shapes_is_refused_by_the_window_too() {
        let s = secrets::Store::file(&tmp("both-shapes"));
        let kit = kit_with(
            "[host]\nbase_path = \"C:\\\\Bases\\\\Старая\"\n\n[[connection]]\nname = \"Ромашка\"\nbase_path = \"C:\\\\Bases\\\\Ромашка\"\n",
        );
        let e = format!("{:#}", Cfg::load_with(&kit, &s).unwrap_err());
        assert!(e.contains("соединение"), "{e}");
        let e = format!("{:#}", Cfg::load_unchecked_with(&kit, &s).unwrap_err());
        assert!(e.contains("соединение"), "окно отказывает тем же словом, не открывается на списке рядом: {e}");
    }

    /// Круг починки 1, находка D: опечатка в `current` не имеет права запирать
    /// окно — оно единственное место, где её исправят. Та же развилка, что у
    /// неоткрывшегося пароля: `load` отказывает, `load_unchecked` терпит и
    /// говорит.
    #[test]
    fn a_misspelled_current_refuses_the_command_line_but_lets_the_window_in() {
        let s = secrets::Store::file(&tmp("bad-current"));
        let kit = kit_with(
            "current = \"Ромашк\"\n\n[[connection]]\nname = \"Ромашка\"\nbase_path = \"C:\\\\Bases\\\\Ромашка\"\n\n[[connection]]\nname = \"Buh\"\nbase_path = \"C:\\\\Bases\\\\Buh\"\n",
        );
        let e = format!("{:#}", Cfg::load_with(&kit, &s).unwrap_err());
        assert!(e.contains("Ромашк»") || e.contains("«Ромашк"), "отказ называет ненайденное имя: {e}");

        let c = Cfg::load_unchecked_with(&kit, &s).expect("окно обязано открыться — в нём опечатку и правят");
        assert_eq!(c.current().name, "Ромашка", "текущим взято первое соединение списка");
        assert_eq!(c.read_notes.len(), 1, "{:?}", c.read_notes);
        let note = &c.read_notes[0];
        assert!(note.contains("Ромашк") && note.contains("Ромашка"), "названы оба имени — ненайденное и взятое: {note}");
    }

    /// Карточка, дописанная в файл РУКАМИ, получает ключ сама — и получает один и тот же при каждом чтении (решение владельца 10.11).
    ///
    /// Файл устроен под ручную правку: его копируют и дописывают в него блоки `[[connection]]`, а ключа человек не пишет и придумать не
    /// может. Поэтому блок без ключа — не отказ и не пустой ключ.
    ///
    /// Второе чтение сверяется НАРОЧНО, и это главное в этом тесте. Записать ключ на диск при чтении запрещено (`reading_does_not_rewrite_the_file`),
    /// значит до первого сохранения ключ живёт только выводом — и если бы вывод был случайным, второе чтение дало бы другой ключ, а все
    /// разрешения, выданные человеком между двумя запусками, молча перестали бы относиться к его карточке.
    #[test]
    fn a_hand_written_card_gets_its_key_by_itself() {
        let s = secrets::Store::file(&tmp("derived-id"));
        let kit = kit_with("current = \"Ромашка\"\n\n[[connection]]\nname = \"Ромашка\"\nbase_path = \"C:\\\\Bases\\\\Ромашка\"\n");
        let first = Cfg::load_unchecked_with(&kit, &s).expect("блок без ключа читается без отказа");
        let id = first.current().id();
        assert!(!id.as_str().is_empty(), "ключ у карточки есть, хотя в файле его нет");
        assert!(first.read_notes.is_empty(), "о своей обычной работе файл человеку не докладывает: {:?}", first.read_notes);
        assert_eq!(
            Cfg::load_unchecked_with(&kit, &s).unwrap().current().id(),
            id,
            "второе чтение обязано дать ТОТ ЖЕ ключ, иначе разрешения карточки не переживут перезапуск"
        );
        // Карточка без пути к базе — тот же случай и тот же ответ: ключ считается от ИМЕНИ, а не от пути, поэтому две только что
        // заведённые (у обеих путь пуст) ключ не делят. Прежний признак базы делил, и это стоило ветке отдельного круга починки.
        let empty = kit_with("current = \"А\"\n\n[[connection]]\nname = \"А\"\n\n[[connection]]\nname = \"Б\"\n");
        let two = Cfg::load_unchecked_with(&empty, &s).unwrap();
        assert_ne!(two.connections[0].id(), two.connections[1].id(), "карточки без пути к базе обязаны иметь РАЗНЫЕ ключи");
    }

    /// Блок, скопированный целиком (а образец прямо этому и учит), несёт копию ключа — и две карточки с одним ключом значили бы, что
    /// зачисление одной читается как зачисление другой. Разводятся они сами, и человеку об этом говорится СЛОВАМИ: ключ он не правил, и
    /// объяснить, почему вторая карточка «забыла» разрешения, иначе будет нечем.
    ///
    /// Ключ в споре остаётся за ПЕРВОЙ карточкой по тексту файла — она при своих зачислениях; второй ключ выводится от её имени.
    #[test]
    fn two_copied_blocks_do_not_share_one_card_key() {
        let s = secrets::Store::file(&tmp("twin-id"));
        let kit = kit_with(
            "current = \"Ромашка\"\n\n[[connection]]\nname = \"Ромашка\"\nid = \"одинаковый\"\nbase_path = \"C:\\\\Bases\\\\Ромашка\"\n\n[[connection]]\nname = \"Buh\"\nid = \"одинаковый\"\nbase_path = \"C:\\\\Bases\\\\Buh\"\n",
        );
        let c = Cfg::load_unchecked_with(&kit, &s).expect("повтор ключа — не повод не открыть окно");
        assert_eq!(c.connections[0].id().as_str(), "одинаковый", "первая карточка остаётся при своём ключе");
        assert_eq!(c.connections[1].id(), CardId::from_name("Buh"), "второй ключ выведен от её имени");
        assert_eq!(c.read_notes.len(), 1, "{:?}", c.read_notes);
        assert!(c.read_notes[0].contains("Buh"), "сказано именно про ту карточку, которой ключ поменяли: {}", c.read_notes[0]);
    }

    /// ОБРАТНЫЙ порядок близнецов — находка проверки безопасности 10.11, которую первый заход пропускал мимо.
    ///
    /// У первой карточки ключ в файле СТОИТ, у второй его нет, и вывод от её имени даёт ровно тот же. Проверка написанного в файле на
    /// второй карточке не срабатывает вовсе (писать там нечего), и близнецы уходили в книгу допуска живыми — то есть зачисления одной
    /// карточки читались как зачисления другой.
    ///
    /// Случай не бытовой: нужно, чтобы в файле стояло число, равное отпечатку ЧУЖОГО имени, — руками так не промахнуться. Стережётся он
    /// не ради частоты, а чтобы «действующие ключи различны» было просто верным, а не почти.
    #[test]
    fn a_twin_key_is_caught_in_the_other_order_too() {
        let s = secrets::Store::file(&tmp("twin-id-reverse"));
        // В файл первой карточке кладётся ровно тот ключ, который вывелся бы ВТОРОЙ от её имени.
        let stolen = CardId::from_name("Вторая");
        let kit = kit_with(&format!(
            "current = \"Первая\"\n\n[[connection]]\nname = \"Первая\"\nid = {:?}\n\n[[connection]]\nname = \"Вторая\"\n",
            stolen.as_str()
        ));
        let c = Cfg::load_unchecked_with(&kit, &s).expect("повтор ключа — не повод не открыть окно");
        assert_eq!(c.connections[0].id(), stolen, "ключ в споре остаётся за той, что в файле раньше");
        assert_ne!(c.connections[1].id(), stolen, "второй карточке обязан достаться СВОЙ ключ, а не общий с первой");
        assert_eq!(c.read_notes.len(), 1, "{:?}", c.read_notes);
        assert!(c.read_notes[0].contains("Вторая"), "сказано про ту карточку, которой ключ развели: {}", c.read_notes[0]);
        // И он тот же при каждом чтении: запись на пути чтения запрещена, значит разводка обязана быть выводом, а не случайностью.
        assert_eq!(Cfg::load_unchecked_with(&kit, &s).unwrap().connections[1].id(), c.connections[1].id());
    }

    /// ЗАПИСАННЫЙ ключ сильнее ВЫВЕДЕННОГО — Important второго ревью всей ветки, и это обычный бытовой путь, а не редкость.
    ///
    /// Человек переименовал карточку: переименование закрепило в файле ключ, выведенный из ПРЕЖНЕГО имени. Освободившееся имя он дописал
    /// руками новым блоком — и дописал ВЫШЕ (образец копируют и правят как придётся). Отпечаток прежнего имени у нового блока выводится
    /// тот же, записанного ключа у него нет вовсе, и пока спор решался порядком в файле, он выигрывал: зачисления переименованной
    /// карточки читались как зачисления новой, пустой, а следующее сохранение закрепляло подмену.
    ///
    /// Прежний тест (`a_twin_key_is_caught_in_the_other_order_too`) стерёг ровно обратный порядок и этот пропускал мимо.
    #[test]
    fn a_written_card_key_beats_a_derived_one_whatever_the_order_in_the_file() {
        let s = secrets::Store::file(&tmp("twin-id-written-wins"));
        // Ключ переименованной карточки — отпечаток имени, которое теперь носит блок ВЫШЕ неё.
        let settled = CardId::from_name("Ромашка");
        let kit = kit_with(&format!(
            "current = \"Василёк\"\n\n[[connection]]\nname = \"Ромашка\"\n\n[[connection]]\nname = \"Василёк\"\nid = {:?}\n",
            settled.as_str()
        ));
        let c = Cfg::load_unchecked_with(&kit, &s).expect("повтор ключа — не повод не открыть окно");

        assert_eq!(c.connections[1].id(), settled, "спорный ключ остаётся у той карточки, у которой он ЗАПИСАН");
        assert_ne!(c.connections[0].id(), settled, "дописанной руками карточке достаётся свой ключ, а не чужие зачисления");
        assert_eq!(c.read_notes.len(), 1, "{:?}", c.read_notes);
        let note = &c.read_notes[0];
        assert!(note.contains("Ромашка"), "сказано про ту карточку, которой ключ развели: {note}");
        assert!(note.contains("Василёк"), "и НАЗВАНА та, у которой зачисления остались: {note}");
    }

    /// Задача 6 (правило речи) и Important второго ревью всей ветки: отказ проверки в ОКНЕ не называет ни ключей toml, ни их значений —
    /// а тот же отказ в консоли называет и то и другое. Проверяется на НАСТОЯЩИХ отказах `validate()`, а не на выдуманной строке.
    #[test]
    fn a_refusal_shown_in_the_window_names_no_toml_key() {
        let mut c = filled_for_test();
        c.current_mut().publication = "чепуха".into();
        let for_file = format!("{:#}", c.validate().unwrap_err());
        let said = said_in_window(&for_file);
        assert!(!said.contains("publication"), "в окне имени ключа toml нет: {said}");
        assert!(said.contains("публикует"), "а поле названо словами человека: {said}");
        assert!(for_file.contains("[publication"), "читателю файла ключ остаётся — этой же фразой отвечает 1c-connect check: {for_file}");

        // Закрытый набор значений — тоже хвост для файла: в окне эту величину ВЫБИРАЮТ, а не пишут словом.
        c.current_mut().mode = "мусор".into();
        let for_file = format!("{:#}", c.validate().unwrap_err());
        let said = said_in_window(&for_file);
        assert!(!said.contains("mode") && !said.contains("tunnel"), "ни ключа, ни его значений: {said}");
        assert!(said.contains("одна ли это машина"), "а величина названа так, как она подписана на экране: {said}");
        assert!(for_file.contains("local, tunnel"), "годные значения остаются читателю файла: {for_file}");

        // Фразы без хвоста функция не портит, и незакрытой скобки не боится.
        assert_eq!(said_in_window("всё хорошо"), "всё хорошо");
        assert_eq!(said_in_window("хвост не закрыт [base_path"), "хвост не закрыт [base_path");

        // ИМЯ КАРТОЧКИ человек пишет сам, и скобки в нём — его скобки. Снимается
        // один хвост и только с конца: прежде снимались все « […]» по строке, и
        // карточка «Ромашка [старая]» теряла в окне половину своего имени — то
        // есть отказ говорил про карточку, которой в списке не видно.
        c.current_mut().name = "Ромашка [старая]".into();
        c.current = "Ромашка [старая]".into();
        c.current_mut().mode = "мусор".into();
        let said = said_in_window(&format!("{:#}", c.validate().unwrap_err()));
        assert!(said.contains("Ромашка [старая]"), "имя карточки доходит до человека целиком: {said}");
        assert!(!said.contains("mode"), "а хвост для файла всё-таки снят: {said}");
    }

    /// Круг починки 1, находка C, закрытая ТИПОМ: перенос потолка записи на
    /// пустой список больше не теряется и карточку по-прежнему не создаёт.
    /// Прежде потолок был полем карточки — и перенос на пустой список либо
    /// заводил карточку-фантом, либо пропадал; теперь переносить его некуда,
    /// кроме как в поле машины, и оба исхода невыразимы.
    #[test]
    fn carrying_the_write_ceiling_onto_an_empty_list_creates_nothing() {
        let fresh = Cfg::default().with_access("read_write");
        assert!(fresh.connections.is_empty(), "соединение из переключателя меню не рождается");
        assert!(fresh.allows_write(), "потолок — свойство машины: карточек для него не требуется");
        // А там, где соединение есть, перенос не задевает саму карточку.
        let one = filled_for_test().with_access("read_write");
        assert!(one.allows_write());
        assert_eq!(one.connections.len(), 1, "и второго соединения не появилось");
        assert_eq!(one.current().write, filled_for_test().current().write, "право записи карточки не тронуто");
        assert!(one.validate().is_ok(), "{:?}", one.validate().err());
    }

    /// Старый файл человека читается БЕЗ ОТКАЗА, и потолок в нём не теряется:
    /// корневого ключа там нет, а значение лежит в блоке ТЕКУЩЕЙ карточки —
    /// ровно там, откуда его вчера брала `access()`. Перенос читает именно
    /// текущую: потолок машины один, и брать «по максимуму» из чужой карточки
    /// значило бы расширить право записи, которого человек не расширял.
    #[test]
    fn an_old_file_without_the_root_key_keeps_the_ceiling_it_had() {
        let old = "current = \"Ромашка\"\n\n[[connection]]\nname = \"Buh\"\nwrite = \"read_only\"\n\n[[connection]]\nname = \"Ромашка\"\nwrite = \"read_write\"\n";
        let c: Cfg = toml::from_str(old).expect("старый файл обязан читаться без отказа");
        assert!(c.read_notes.is_empty(), "и без находок: {:?}", c.read_notes);
        assert_eq!(c.access(), "read_write", "потолок взят из текущей карточки");

        let swapped = old.replacen("current = \"Ромашка\"", "current = \"Buh\"", 1);
        let c: Cfg = toml::from_str(&swapped).unwrap();
        assert_eq!(c.access(), "read_only", "текущая другая — и потолок её");
    }

    /// Потолок записи СЕГОДНЯ — корневой ключ файла, и стережёт его этот тест, а не перенос старого файла рядом.
    ///
    /// **Почему отдельным тестом** (Important второго ревью всей ветки). До этой правки «корневой ключ сильнее переноса» проверялось
    /// третьим утверждением внутри теста про СТАРЫЙ файл — то есть на заготовке, у которой потолок лежит в блоках карточек. Такая
    /// заготовка зеленеет и у продукта, который корневого ключа не умеет вовсе: достаточно, чтобы работал перенос. Здесь наоборот —
    /// ключ есть ТОЛЬКО в корне, и ни одна карточка потолка не называет: мера та самая, которой продукт сегодня и пишет
    /// (`gui::save::save_tray_ceiling` правит корень, `render` его печатает).
    #[test]
    fn the_write_ceiling_lives_in_the_root_key_and_asks_no_card() {
        let root = "write = \"read_write\"\ncurrent = \"Buh\"\n\n[[connection]]\nname = \"Buh\"\n\n[[connection]]\nname = \"Ромашка\"\n";
        let c: Cfg = toml::from_str(root).expect("файл с корневым потолком читается без отказа");
        assert_eq!(c.access(), "read_write", "потолок прочитан из корня: карточки о нём не сказали ничего");
        assert!(c.allows_write());
        assert!(c.connections.iter().all(|c| c.write.is_empty()), "заготовка нарочно без потолков в карточках");
        // И корень сильнее переноса там, где сказали оба: карточка себе запрещает, машина разрешает — и потолок МАШИНЫ не сужается.
        let both = root.replace("name = \"Buh\"\n", "name = \"Buh\"\nwrite = \"read_only\"\n");
        let c: Cfg = toml::from_str(&both).unwrap();
        assert_eq!(c.access(), "read_write", "корневой ключ переноса из карточки не спрашивает вовсе");
        assert!(!c.may_write(c.current()), "а своей базе карточка запись запретила — и это другой вопрос, не потолок машины");
    }

    /// Файла без ключа `write` вовсе (ни в корне, ни в карточках) бояться
    /// нечего: умолчание — «только чтение», решение владельца 1.11.
    #[test]
    fn a_file_without_any_write_key_at_all_reads_as_read_only() {
        let c: Cfg = toml::from_str("current = \"Buh\"\n\n[[connection]]\nname = \"Buh\"\n").expect("читается без отказа");
        assert_eq!(c.access(), "read_only");
        assert!(!c.allows_write());
    }

    /// Именованный мусор в корневом потолке — отказ СЛОВАМИ со списком
    /// допустимых, как у `toolset`/`role`, а не английское «unknown variant»
    /// от serde и не молчаливый откат.
    #[test]
    fn an_unknown_root_ceiling_is_refused_with_words() {
        let e = toml::from_str::<Cfg>("write = \"может быть\"\ncurrent = \"\"\n").unwrap_err().to_string();
        assert!(e.contains("read_write") && e.contains("read_only"), "{e}");
        assert_eq!(WriteCeiling::try_from(String::new()), Ok(WriteCeiling::ReadOnly), "пустое значение — умолчание, не отказ");
    }

    /// Буквально из брифа задачи 3: текущее соединение берётся ИЗ СПИСКА, а
    /// не живёт отдельным полем — правка текущего меняет сам список, а не
    /// копию рядом с ним, и пустой список отдаёт пустое соединение, а не
    /// панику (окно обязано открыться до первой настройки).
    #[test]
    fn the_current_connection_comes_from_the_list() {
        let mut c = cfg_with(&["Buh", "Ромашка"]);
        c.current = "Ромашка".into();
        assert_eq!(c.current().name, "Ромашка");
        c.current_mut().db_user = "mcp".into();
        assert_eq!(c.connections.iter().find(|x| x.name == "Ромашка").unwrap().db_user, "mcp", "правка текущего меняет список, а не копию");

        // Свежий комплект: соединений нет вовсе, и окно обязано открыться.
        let fresh = Cfg::default();
        assert_eq!(fresh.current().name, "", "пустой список отдаёт пустое соединение, а не панику");
    }

    /// Отказ по умолчанию живёт у ПОТОЛКА МАШИНЫ, и ничто кроме точного
    /// `read_write` его не снимает: пустой файл, опечатка, иной регистр — всё
    /// это «только чтение» (решение владельца 1.11). Третьего значения у типа
    /// нет, поэтому проверяется то, что приходит снаружи, — слово из файла.
    #[test]
    fn the_machine_ceiling_denies_by_default_and_opens_only_on_the_exact_word() {
        assert_eq!(Cfg::default().access(), "read_only", "пусто — запрет");
        assert!(!Cfg::default().allows_write());
        assert!(WriteCeiling::try_from("READ_WRITE".to_string()).is_err(), "регистр не точный — отказ словами, не разрешение");
        assert!(WriteCeiling::try_from("мусор".to_string()).is_err());
        assert_eq!(WriteCeiling::try_from("read_write".to_string()), Ok(WriteCeiling::ReadWrite));
        assert!(!filled().with_access("READ_WRITE").allows_write(), "неизвестное слово — запрет, а не разрешение");
    }

    /// Право записи КАРТОЧКИ — запрет, а не разрешение: пустое поле ничего не
    /// запрещает (всё решает потолок машины, контракт: «действует на все
    /// соединения этой машины разом»), а `read_only` запрещает даже при
    /// открытом потолке. Разрешить больше потолка карточка не может.
    #[test]
    fn a_card_can_only_forbid_itself_never_allow_beyond_the_machine() {
        let mut c = filled();
        c.current_mut().write = String::new();
        assert_eq!(c.current().write_rule(), CardWrite::Unset);
        assert!(!c.may_write_now(), "машина закрыта — итог запрет, что бы ни молчала карточка");
        c = c.with_access("read_write");
        assert!(c.may_write_now(), "открыли машину, карточка не против — пишем");
        c.current_mut().write = "read_only".into();
        assert_eq!(c.current().write_rule(), CardWrite::Forbidden);
        assert!(!c.may_write_now(), "карточка запрещает себе и при открытом потолке");
        assert!(c.allows_write(), "а потолка машины это не меняет — он не её поле");
    }

    /// Красный тест поправки ведущего (1): нераспознанное слово у карточки
    /// ЗАПРЕЩАЕТ запись, а не разрешает её. Опечатка `readonly`, иной
    /// регистр, мусор из недочитанного файла — все они проходят мимо
    /// `validate()` (окно обязано открыться на файле с опечаткой), и
    /// единственное, что стоит между ними и записью в чужую базу, — отказ по
    /// умолчанию здесь.
    #[test]
    fn an_unrecognised_word_on_a_card_forbids_writing_never_allows_it() {
        let mut c = filled().with_access("read_write");
        for word in ["readonly", "READ_ONLY", "read only", "мусор", "read_write  х"] {
            c.current_mut().write = word.into();
            assert_eq!(c.current().write_rule(), CardWrite::Forbidden, "«{word}» — запрет");
            assert!(!c.may_write_now(), "«{word}» не имеет права открывать запись в базу");
            assert!(!c.current().allows_write(), "и вторая половина, которую складывает провод, тоже запрет: «{word}»");
        }
        c.current_mut().write = "read_write".into();
        assert!(c.may_write_now(), "точное слово — и только оно — разрешает");
    }

    /// Красный тест поправки ведущего (2): обе половины программы берут
    /// действующее право из ОДНОГО места. Карточка «Только чтение» при
    /// машине «Полный» не даёт писать ни местному агенту (через
    /// `may_write_now` — её спрашивает мост), ни той стороне по проводу
    /// (`Connection::allows_write` — её множит `peer::Machine::of` на
    /// потолок машины). Прежде мост спрашивал один потолок машины, и человек
    /// видел на экране запрет, которого нет.
    #[test]
    fn the_wire_and_the_local_bridge_cannot_disagree_about_the_same_card() {
        let mut c = filled().with_access("read_write");
        c.current_mut().write = "read_only".into();
        assert!(!c.may_write_now(), "местный агент через мост — запрет");
        assert!(!(c.current().allows_write() && c.allows_write()), "и на проводе, где складывают те же две половины, — запрет");
        assert!(!c.may_write(c.current()), "обе половины — одна мера, и мера одна и та же");
    }

