        assert_eq!(derived_base_url("C:\\Bases\\Buh\\"), "http://localhost/Buh/hs/mcp-1c");
        assert_eq!(derived_base_url(""), "http://localhost/Buh/hs/mcp-1c");
        // Имя папки, которое `validate` не пропустит, — то же умолчание.
