    /// Задача 6 плана «Интерфейс»: замок на пустом `base_path` держит много
    /// потребителей, но смысл у него один — непустой путь нужен только там,
    /// где человек сам сказал «база здесь» (`base_here`). У соединения, чья
    /// база на той стороне, своих полей базы в карточке нет вовсе
    /// (`panel::shown_fields`), и требовать от него путь, которого окно не
    /// показывает, значило бы запирать программу на поле, заполнить которое
    /// нечем.
    #[test]
    fn an_empty_base_path_is_not_a_lock_where_the_base_is_elsewhere() {
        // `filled()` — явно, не `Connection::default()` (круг починки 2
        // задачи 12): умолчание — `mode = "local"`, и с этого круга
        // `validate()` спрашивает `base_is_here()`, а не сырое поле —
        // «база на той стороне» требует настоящего туннельного режима, а
        // не просто `base_here = false` при умолчании, которое САМО
        // означает «база здесь» (находка координатора, та же, что уже
        // поправила три фикстуры `panel.rs` в прошлом круге).
        let mut cfg = filled();
        cfg.current_mut().base_here = false;
        cfg.current_mut().base_path = String::new();
        assert!(cfg.current().validate().is_ok(), "{:?}", cfg.current().validate().unwrap_err());
    }

    #[test]
    fn tools_default_to_the_working_set() {
        let c = sample();
        assert_eq!(c.current().tools, DEFAULT_TOOLS.iter().map(|s| s.to_string()).collect::<Vec<_>>());
        assert!(c.current().tools.contains(&"cf_load".to_string()) && !c.current().tools.contains(&"xunit".to_string()));
    }

    /// Серверы MCP у pi и у Zed — одно и то же, иначе агенты разойдутся в
    /// умениях и никто не поймёт, почему один знает про выгрузку, а другой
    /// нет. Проверяется не только список имён: `command`, `args` и предел
    /// времени — это и есть всё содержимое записи о сервере.
    ///
    /// Форма у pi своя (`mcpServers` вместо `context_servers`, нет поля
    /// `source`), а `timeout` у обоих в секундах — значит числа переносятся
    /// один в один.
    #[test]
    fn pi_declares_the_same_mcp_servers_as_zed() {
        const PI: &str = include_str!("../../../config/pi/mcp.json");
        let pi: serde_json::Value = serde_json::from_str(PI).expect("config/pi/mcp.json — обычный JSON, без комментариев");
        let zed = zed_json();
        let z = zed["context_servers"].as_object().expect("в настройках Zed есть context_servers");
        let p = pi["mcpServers"].as_object().expect("в mcp.json есть mcpServers");

        let mut zn: Vec<&str> = z.keys().map(String::as_str).collect();
        let mut pn: Vec<&str> = p.keys().map(String::as_str).collect();
        zn.sort();
        pn.sort();
        assert_eq!(zn, pn, "серверы MCP у pi и у Zed разошлись");

        for name in zn {
            // `env` сверяется тоже, хотя сейчас его нет ни у кого:
            // появится он сперва у Zed, и расхождение прошло бы молча.
            for field in ["command", "args", "timeout", "env"] {
                assert_eq!(z[name][field], p[name][field], "сервер {name}: поле {field} у pi и у Zed разошлось");
            }
        }
    }

    #[test]
    fn render_keeps_comments_and_round_trips() {
        let store = secrets::Store::file(&tmp("render-roundtrip"));
        let mut c = sample();
        // Образец ключа карточки не показывает (решение владельца 10.11: человек его не пишет), а печать — дописывает: иначе ключ не
        // доехал бы на диск ни разу. Всё остальное в печати совпадает с образцом буква в букву, объяснения человеку включая, — поэтому
        // сверяется печать БЕЗ строки ключа, а сам ключ проверяется отдельно строкой ниже.
        let printed = c.render(&store).unwrap();
        assert_eq!(without_card_key(&printed), EXAMPLE, "печать расходится с образцом не только ключом карточки");
        assert!(printed.contains(&format!("id = {:?}", c.current().id().as_str())), "ключ карточки в печать не попал");
        // И это то самое «первое сохранение», которым ключ ложится на диск: напечатанный файл читается обратно, и ключ в нём уже свой,
        // а не выведенный заново.
        let back: Cfg = toml::from_str(&printed).unwrap();
        assert_eq!(back.current().id_in_file, c.current().id(), "сохранение обязано записать ключ в файл, а не вывести его опять");
        let t = c.render(&store).unwrap();
        // Объяснение поля — в шапке над блоками (решение плана 4), и
        // печать его не теряет.
        assert!(t.contains("base_path = ") && t.contains("# base_path — путь к файловой базе"));
        // Прочитанное обратно отличается от напечатанного РОВНО ключом в файле: у `c` его не было (образец его не несёт), печать его
        // вывела и записала. Записываем то же в `c` — и дальше круг обязан быть полным, поле к полю.
        let settled = c.current().id();
        c.current_mut().id_in_file = settled;
        assert_eq!(toml::from_str::<Cfg>(&t).unwrap(), c);
    }

